const seenIds = new Set<string>();
const diagnostics: Diagnostic[] = [];
for (const occurrence of occurrences) {
    if (seenIds.has(occurrence.id)) {
      diagnostics.push({
        code: 'OARC-E011',
        id: occurrence.id,
        file: occurrence.file,
      });
    } else {
      seenIds.add(occurrence.id);
    }
  }
return diagnostics;
